const T = (concept, scenario, trace, mistake, question, answer) => ({ concept, scenario, trace, mistake, question, answer });
export const networkRoadmapContent = {
  "20-must-know-networking-concepts": T("Use twenty anchors to organize networking: host, interface, MAC address, IP address, subnet, gateway, switch, router, port, socket, packet, frame, DNS, DHCP, TCP, UDP, HTTP, TLS, latency, and bandwidth. Relate each to naming, local delivery, routing, transport, application behavior, or performance rather than memorizing disconnected definitions.", "A laptop obtains configuration through DHCP, resolves a hostname through DNS, sends frames through a gateway, and reaches an HTTPS service using IP, transport, and TLS.", "Configure|DHCP supplies address and route|Local connectivity;Locate|DNS returns service address|Naming;Connect|Transport plus TLS plus HTTP|Application exchange", "An IP address identifies a network-layer destination, while a port helps demultiplex transport endpoints; neither alone identifies a business operation.", "Which concepts distinguish a slow lookup from a slow download?", "DNS concerns naming, while transfer speed depends on latency, available bandwidth, transport behavior, and the server's production rate."),
  "what-happens-when-you-type-a-url": T("A browser parses the URL, checks applicable caches and policies, resolves a name if needed, establishes or reuses a transport connection, negotiates TLS for HTTPS, sends an HTTP request, and processes the response. Redirects, proxies, connection reuse, and HTTP version alter the path. Rendering may trigger many additional requests.", "For a cold HTTPS request, distinguish DNS time, connection setup, TLS negotiation, server time, and response transfer rather than attributing everything to the server.", "Resolve|Hostname becomes endpoint|Cache may avoid lookup;Connect|Transport and TLS established|Identity validated;Fetch|HTTP response arrives|Parsing may request more resources", "A warm connection can skip setup stages, so cold and reused requests are different benchmarks.", "Why can the HTML arrive quickly while the page remains slow?", "Scripts, styles, images, parsing, and main-thread execution can dominate after the initial document response."),
  "osi-7-layer-model": T("The OSI model separates physical signaling, data-link delivery, network routing, transport, session, presentation, and application responsibilities. It is a reasoning framework rather than a promise that deployed protocols fit one layer perfectly. Use it to locate failures and distinguish adjacent-hop delivery from end-to-end application semantics.", "A cable failure is below IP routing; an expired certificate is not fixed by changing Ethernet framing; an HTTP authorization failure occurs after connectivity works.", "Link|Check physical and frame delivery|Lower layers;Transport|Check endpoint communication|Ports and reliability;Application|Check TLS and HTTP semantics|Higher-layer behavior", "TLS and real-world middleware do not map neatly to a single universal OSI box.", "Why is layering useful in debugging?", "It narrows which guarantees have already been established and prevents changing unrelated components when a higher-layer check fails."),
  "tcp-ip-4-layer-model": T("The TCP/IP model commonly groups link, internet, transport, and application layers. IP provides addressing and forwarding without reliable ordered delivery; TCP or UDP defines transport behavior; applications define message meaning. Link technologies carry packets across each local hop, and those link headers can change along a route.", "An HTTP message travels inside TCP segments, IP packets, and Ethernet frames. A router replaces local link framing while forwarding the IP packet.", "Application|HTTP bytes|Meaning defined by HTTP;Transport|TCP stream carried by IP|End-to-end endpoints;Link|Frame for next hop|Changes across routed links", "Transport reliability does not guarantee that the remote application committed a requested business action.", "Where does DNS fit in the TCP/IP model?", "It is an application protocol that can use different underlying transports; its naming role does not make it an IP-layer protocol."),
  "packet-structure-and-encapsulation": T("Encapsulation adds headers, and sometimes trailers, around a higher-layer payload. Each layer uses its own fields for delivery and interpretation. MTU limits constrain the size carried by a link; transport segmentation and IP fragmentation are distinct mechanisms. Payload size therefore differs from bytes transmitted on the wire.", "A 1,460-byte TCP payload with a 20-byte TCP header and 20-byte IPv4 header fits a 1,500-byte IP MTU when no options are present.", "Payload|1460 application bytes|Simplified TCP example;Headers|Add 20 TCP plus 20 IPv4|1500-byte IP packet;Frame|Add link overhead separately|Wire bytes exceed payload", "TCP/IP options, IPv6 headers, tunnels, and encryption can change overhead; state assumptions before calculating.", "Why can a tunnel break large transfers?", "Extra headers reduce effective payload capacity, and broken path-MTU discovery can leave oversized packets repeatedly lost."),
  "network-types-lan-wan-vpn": T("A LAN connects nearby endpoints under local link administration, while a WAN connects broader regions through routed infrastructure. The Internet interconnects independently operated networks. A VPN creates a protected or logically private overlay across another network; it does not remove the underlying path's latency, congestion, or trust requirements at endpoints.", "A remote employee reaches a private service through a VPN over home broadband. Diagnose the local Wi-Fi, Internet route, tunnel, and service separately.", "Local|Laptop reaches home gateway|LAN;Transit|Packets cross provider networks|WAN and Internet;Overlay|VPN carries private traffic|Additional routing and encryption", "Private addressing alone is not encryption or authentication.", "Does a VPN make a slow path fast?", "No. It can change routing and protection, but still depends on underlying capacity and may add overhead."),
  "ethernet-and-frames": T("Ethernet frames carry source and destination MAC addresses, a type/length field, payload, and error-detection information. A frame is local-link delivery, not the entire end-to-end routed journey. Switches learn source locations and forward based on destination tables; invalid frames can be discarded without providing application-level recovery.", "A host sends an IP packet to a remote subnet by placing it in a frame addressed to its local gateway's MAC, not the remote host's MAC.", "Host|IP destination is remote|Route selects gateway;Frame|Destination MAC is gateway|Local-hop delivery;Router|Builds next-hop frame|IP forwarding continues", "Ethernet error detection does not promise retransmission or business-level delivery.", "Why are IP and MAC destinations different here?", "IP identifies the routed endpoint, while the MAC destination selects the next receiver on the current local link."),
  "mac-vs-ip-addresses": T("A MAC address participates in local link delivery, whereas an IP address participates in routed network addressing. IP prefixes encode routing structure; MAC values generally do not provide Internet routing hierarchy. Interfaces can change or randomize MAC addresses, so neither address should be treated as a permanent trustworthy user identity.", "A laptop moves from home to office Wi-Fi. Its IP configuration changes, and its link-layer identity may also differ under privacy settings.", "Home|Address belongs to home subnet|Local route;Move|Join office network|New link context;Configure|Obtain office IP|Different routing prefix", "A MAC address is not normally carried unchanged across every router to a remote server.", "Why not route the Internet by flat MAC addresses?", "Hierarchical IP prefixes allow aggregation; a global flat table for every interface would scale poorly and complicate policy."),
  "switches-hubs-routers": T("A hub repeats physical signals, a switch forwards local frames using learned link addresses, and a router forwards packets between networks using routing entries. Broadcast domains and collision behavior differ. Modern devices can combine these functions, so identify the operation being performed rather than relying only on the product name.", "Two hosts in one subnet exchange frames through a switch. Reaching another subnet requires a route through a router, even if one appliance implements both roles.", "Learn|Switch observes source MAC|Build local table;Local|Forward frame to known port|Same link domain;Route|Router selects destination prefix|Cross network boundary", "A switch's unknown-destination flooding is not the same as routing a packet to every network.", "What does a router change at a hop?", "It decrements the IP lifetime field and constructs suitable next-link framing, with other changes depending on features such as NAT."),
  "arp-protocol": T("ARP resolves an IPv4 next-hop address to a link-layer address on a local broadcast domain. A host broadcasts a request and caches a response for later delivery. For off-subnet traffic it resolves the gateway, not the final remote host. IPv6 uses Neighbor Discovery rather than ARP.", "Host 192.0.2.10 sends to a remote network via 192.0.2.1. It asks who owns 192.0.2.1 and uses the returned MAC for the outgoing frame.", "Route|Choose gateway 192.0.2.1|Remote destination;ARP|Broadcast gateway lookup|Local network;Send|Frame uses gateway MAC|IP destination remains remote", "ARP responses are not inherently authenticated; local spoofing can misdirect traffic.", "Why can ping fail before any ICMP packet leaves?", "The host may be unable to resolve its next-hop link address, so local delivery cannot begin."),
  "vlans-and-segmentation": T("A VLAN partitions a switched network into logical broadcast domains, commonly using 802.1Q tags on trunks. Access ports usually associate untagged endpoint traffic with a configured VLAN. Communication between VLANs requires routing and should apply explicit policy. Segmentation reduces broadcast scope and separates trust zones but is not a replacement for application authentication.", "Place employee devices and guest Wi-Fi in separate VLANs, then permit only the intended routed access from guests to external services.", "Ingress|Assign frame to guest VLAN|Separate broadcast domain;Switch|Forward within VLAN|No ordinary cross-VLAN flooding;Router|Apply inter-VLAN policy|Controlled communication", "A VLAN identifier alone is not encryption, and trunk misconfiguration can undermine separation.", "Why is a router or layer-3 function needed?", "Different VLANs represent distinct link domains; crossing their IP subnets requires routed forwarding."),
  "wifi-802-11-basics": T("Wi-Fi shares a radio medium using contention and collision-avoidance mechanisms rather than assuming every station can transmit simultaneously without interference. Signal quality, channel overlap, airtime, retries, and client capabilities affect usable throughput. Link rate is a signaling capability, not guaranteed application throughput.", "A laptop reports a high link rate but downloads slowly in a crowded room. Retransmissions and competing airtime can consume capacity before the application sees bytes.", "Contend|Several stations want airtime|Shared channel;Retry|Interference corrupts frames|Extra transmissions;Deliver|Useful payload arrives|Below nominal link rate", "Strong signal strength alone does not rule out congestion, interference, or a slow upstream path.", "Why can a slow client affect others?", "It may occupy more airtime per delivered byte on the shared channel, depending on scheduling and radio conditions."),
  "ipv4-addressing": T("IPv4 uses 32-bit addresses divided by prefixes for routing. Public addresses are limited, while private ranges can be reused within separate networks and translated at boundaries. A host needs an address, prefix, and routing configuration; merely choosing an unused-looking number does not establish reachability or ownership.", "Two homes can both use 192.168.1.10 internally because their private networks are separate. Their external communication depends on distinct public-side routing and translation.", "Private|Same address reused locally|Separate domains;Gateway|Translates or routes traffic|Public-side identity;Internet|Routes globally allocated prefixes|Private overlap hidden", "Private addresses are not globally unique and cannot be assumed reachable across arbitrary connected networks.", "Why does connecting overlapping private networks cause trouble?", "The same destination prefix can refer to different endpoints, requiring renumbering, translation, or explicit routing isolation."),
  "ipv6": T("IPv6 expands addressing to 128 bits, uses a fixed base header with extension mechanisms, and replaces ARP with Neighbor Discovery. It supports unicast, multicast, and anycast rather than IPv4-style broadcast. Hosts can use SLAAC and/or DHCPv6 depending on network policy; dual-stack systems must diagnose each address family independently.", "A hostname returns both A and AAAA records. IPv4 succeeds but IPv6 stalls because the IPv6 route or firewall is broken.", "Resolve|Receive IPv4 and IPv6 candidates|Two possible paths;Attempt|IPv6 path fails|Family-specific issue;Compare|Test IPv4 independently|Do not blame DNS alone", "IPv6 does not automatically provide encryption or eliminate firewall policy requirements.", "Why can blocking ICMPv6 break connectivity?", "Essential control functions, including Neighbor Discovery and path-MTU-related signaling, depend on appropriate ICMPv6 messages."),
  "subnetting-and-cidr": T("CIDR represents a network prefix as an address plus a bit length. Longer prefixes identify smaller ranges, and routers prefer the longest matching route. IPv4 host-count conventions depend on subnet purpose; the familiar subtract-two rule does not apply universally to /31 links or /32 host routes.", "192.0.2.64/26 spans addresses .64 through .127. In a conventional broadcast subnet, .65 through .126 are host addresses, giving 62 usable hosts.", "Prefix|26 network bits|Six host bits;Range|64 addresses total|64 through 127;Hosts|Exclude network and broadcast|62 conventional host addresses", "A prefix length is not the number of hosts, and exceptions must be stated.", "Which wins between /24 and matching /26 routes?", "The /26 is more specific and wins under longest-prefix matching before tie-breaking among equally specific routes."),
  "how-routing-works": T("A router looks up the destination in its forwarding table, selects a next hop and output interface, and forwards with a reduced lifetime field. The control plane builds routes; the data plane uses them. Longest-prefix matching chooses specificity, while metrics and policy resolve eligible alternatives within the routing design.", "A router has a default route, 10.0.0.0/8, and 10.2.0.0/16. A packet to 10.2.3.4 uses the /16 route.", "Lookup|Destination 10.2.3.4|Three matches;Select|Choose longest /16|Most specific;Forward|Resolve next hop and send|Lifetime decreases", "A route in one direction does not guarantee a valid return path.", "Why can asymmetric routing matter?", "Stateful middleboxes and troubleshooting assumptions may depend on seeing both directions, even though IP paths can legitimately differ."),
  "bgp-and-ospf": T("OSPF is a link-state interior routing protocol that computes paths from a topology view within an administrative domain. BGP exchanges reachability and attributes between routing domains and emphasizes policy, not simply shortest physical distance. Convergence, filtering, aggregation, and route validation influence availability and safety.", "An organization prefers one transit provider despite a geographically shorter alternative. BGP policy can choose that path while internal OSPF handles routes inside its network.", "Interior|OSPF distributes link state|Compute internal paths;Exterior|BGP advertises prefixes|Policy and attributes;Select|Apply administrative preference|Not pure distance", "An advertised route is not proof that the origin is legitimate or that the data path is healthy.", "Why can a routing change disrupt traffic briefly?", "Different routers converge at different times, potentially producing temporary loss or inconsistent forwarding until state stabilizes."),
  "nat-and-pat": T("NAT translates network addresses, while port address translation also maps transport ports so multiple internal flows can share a public address. State tracks how return traffic maps back to the internal endpoint. Translation complicates inbound reachability, idle timeouts, and connection identity; it is distinct from a deliberate firewall authorization policy.", "10.0.0.5:50000 is mapped to a public endpoint's port 62000. A reply to 62000 is translated back using the saved flow mapping.", "Outbound|Private tuple 10.0.0.5:50000|New flow;Translate|Public port 62000 assigned|State stored;Reply|Lookup translation state|Deliver to private endpoint", "NAT is not a substitute for authentication or an explicit security policy.", "Why can an idle connection break behind NAT?", "The mapping may expire, so later packets no longer match valid translation state even if the application believes the connection exists."),
  "icmp-ping-traceroute": T("ICMP carries network control and error information. Ping commonly uses echo messages to probe reachability and round-trip time. Traceroute varies TTL or hop limit to elicit intermediate time-exceeded responses; probe transports vary. Routers may rate-limit or deprioritize replies, so missing responses do not necessarily mean forwarded traffic is lost.", "An intermediate hop does not answer traceroute, but later hops and the destination do. The silent router is still forwarding the probes.", "Probe|Lifetime expires at router|ICMP response possible;Silence|Router suppresses reply|Not proof of forwarding failure;Destination|Later probe arrives|Path continues", "A successful ping does not prove that a TCP port, TLS handshake, or application endpoint works.", "Why compare end-to-end loss with hop replies?", "Intermediate response policy can look like loss without affecting transit packets; destination behavior is the stronger end-to-end signal."),
  "dhcp": T("DHCP provides leased host configuration, commonly including an IPv4 address, subnet information, routers, and DNS servers. The familiar initial exchange is discover, offer, request, acknowledge. Lease renewal and rebinding maintain configuration over time. A relay can connect clients to a server outside their immediate broadcast domain.", "A laptop joins a new LAN, requests configuration, receives an offer, and confirms the selected lease before using it under the protocol's rules.", "Discover|Client seeks configuration|Broadcast domain;Offer and request|Choose proposed lease|Server selection;Acknowledge|Lease and options confirmed|Configure route and DNS", "Receiving an IP address alone does not prove the supplied gateway or DNS path is working.", "Why use a lease rather than permanent assignment?", "It allows address reuse and configuration changes while giving clients a defined validity and renewal schedule."),
  "tcp-vs-udp": T("TCP provides an ordered reliable byte stream with flow and congestion control. UDP provides datagrams without built-in delivery, ordering, or retransmission guarantees. Applications may build reliability over UDP, as QUIC does. Choose based on message semantics, latency tolerance, loss handling, and protocol requirements rather than a blanket claim that UDP is faster.", "A live audio stream may prefer dropping a late frame to retransmitting it, while a file transfer needs every byte reconstructed correctly.", "Audio|Late frame has little value|Loss tolerance;File|Missing bytes invalidate content|Reliability needed;Design|Choose transport and recovery policy|Application semantics decide", "UDP applications still need congestion-aware behavior and must handle loss, duplication, and reordering where relevant.", "Does TCP preserve write boundaries?", "No. It preserves byte order, so applications must define framing independently of send and receive call boundaries."),
  "tcp-three-way-handshake": T("TCP connection establishment exchanges SYN, SYN-ACK, and ACK to synchronize sequence spaces and confirm bidirectional communication. SYN consumes one sequence number. Options can negotiate capabilities such as window scaling. The handshake establishes transport state, not application authentication or successful processing of later requests.", "Client ISN is 100 and server ISN is 500. SYN uses 100; SYN-ACK acknowledges 101; the final ACK acknowledges 501.", "SYN|Client seq 100|Connection requested;SYN-ACK|Server seq 500 ack 101|Both sequence spaces known;ACK|Client ack 501|Transport established", "TLS and application authorization are additional steps beyond TCP establishment.", "Why does a server need the final ACK?", "It confirms that the client received the server's sequence-space information and can complete the server's establishment state."),
  "tcp-connection-termination": T("TCP closes each direction independently. FIN marks that one endpoint has no more bytes to send and consumes sequence space; the peer can still send in the other direction. RST aborts a connection. TIME_WAIT protects against delayed segments and supports retransmission handling after an active close.", "A client half-closes its send direction after a request but continues receiving the server's response before fully closing.", "Client FIN|No more request bytes|Send direction ends;Server data|Response still allowed|Reverse direction open;Server FIN|Response complete|Both directions close", "EOF on receive does not automatically mean the application has finished sending its own buffered response.", "Why not remove TIME_WAIT indiscriminately?", "It serves protocol correctness around delayed segments and final acknowledgements; tune connection reuse and capacity before defeating safeguards."),
  "tcp-header-anatomy": T("A TCP header includes source and destination ports, sequence and acknowledgement numbers, flags, advertised window, checksum, and optional extensions. Sequence numbers count bytes, while the acknowledgement indicates the next expected byte in the cumulative model. Header length varies with options, so parsers must not assume every TCP header is exactly 20 bytes.", "A segment starts at sequence 1000 and carries 200 bytes. With contiguous receipt, the peer acknowledges 1200.", "Header|seq 1000 payload 200|Byte-range description;Receive|Bytes 1000 through 1199|Contiguous data;ACK|Next expected 1200|Cumulative progress", "The advertised receive window is not the sender's congestion window.", "What does ACK 1200 mean?", "It acknowledges contiguous sequence space before 1200; it does not prove that the peer application committed those bytes to durable storage."),
  "reliability-acks-retransmission": T("TCP tracks sequence space, acknowledges received data, detects loss through acknowledgements and timers, and retransmits as required. Duplicate or reordered segments can occur, but the receiving stream presents ordered bytes without duplicates. Retransmission timeout estimation adapts to path timing; selective acknowledgements can describe received ranges beyond a gap.", "Segments covering 1000–1099 and 1200–1299 arrive, but 1100–1199 is missing. Cumulative acknowledgement cannot advance beyond the gap until it is filled.", "Receive|First range contiguous|ACK 1100;Gap|Later range arrives|Cumulative ACK stays 1100;Recover|Missing range retransmitted|ACK can advance to 1300", "Transport retransmission does not make repeating an entire application request safe.", "Why might the sender retransmit data already received?", "The acknowledgement may have been lost or delayed, so the sender cannot distinguish that case from lost data without further evidence."),
  "flow-control-sliding-window": T("Flow control limits outstanding data according to the receiver's available buffer space. The advertised receive window moves as bytes are acknowledged and consumed. A sender is also constrained by congestion control, so usable flight capacity depends on both. A zero receive window indicates receiver pressure, not necessarily network packet loss.", "The receiver advertises 8 KiB and 6 KiB are outstanding. Ignoring other constraints, at most 2 KiB more can be sent before further progress.", "Window|Receiver offers 8 KiB|Buffer-based limit;In flight|6 KiB unacknowledged|Capacity partly used;Send|At most 2 KiB extra|Also obey congestion window", "Increasing sender buffers cannot force a receiver to consume data faster.", "What causes a zero-window event?", "The receive buffer is exhausted, often because the application is not reading promptly; investigate consumer progress and buffer policy."),
  "congestion-control": T("Congestion control limits traffic to protect the path rather than the receiver alone. Slow start grows the window rapidly initially; classic AIMD increases cautiously and reduces after congestion. Reno and Cubic use loss-related window behavior with different growth functions, while BBR models bandwidth and round-trip behavior. Exact algorithms and versions differ.", "A sender increases in-flight data until queues grow or loss signals congestion. Reducing the sending rate can improve latency even before throughput rises.", "Probe|Increase sending opportunity|Discover capacity;Congest|Queue or loss signal appears|Path under pressure;Adapt|Reduce or remodel rate|Avoid sustained overload", "Congestion window and receive window represent different constraints, and a particular loss does not always identify its cause.", "Why is maximum possible send rate not always best?", "Excess offered load creates queueing, loss, and retransmissions, increasing latency without increasing useful delivery."),
  "head-of-line-blocking": T("Head-of-line blocking occurs when earlier unfinished work prevents later ready work from being delivered or processed. TCP's ordered byte stream withholds later bytes across a gap. HTTP/2 multiplexes streams but shares one TCP delivery dependency; QUIC separates stream delivery so loss on one stream need not block another stream's ordered data.", "Two HTTP/2 responses share a TCP connection. A missing TCP segment can delay delivery for both even if later packets contain data for the second response.", "Streams|A and B share connection|Multiplexed HTTP;Loss|One TCP byte range missing|Transport ordering gap;Wait|Later bytes withheld|Both streams can stall", "QUIC still has ordering within each stream and shared congestion constraints; it does not eliminate every kind of blocking.", "Why did multiplexing not solve this in HTTP/2?", "It separates application stream framing but still runs over TCP's single ordered byte stream."),
  "udp-internals": T("UDP adds a small header with source port, destination port, length, and checksum around a datagram. Datagram boundaries are preserved, but delivery and ordering are not guaranteed. Large datagrams risk IP fragmentation or path-size problems. Receivers must handle truncation and validate lengths before parsing application fields.", "A receiver supplies a buffer smaller than a datagram. Depending on the API, excess bytes can be discarded rather than available in a later receive call.", "Send|One application datagram|Message boundary;Receive|Buffer too small|Truncation possible;Validate|Check size and truncation indication|Reject incomplete message", "Do not use a TCP-style assumption that the rest of a truncated datagram will arrive on the next read.", "Why keep datagrams below path limits?", "Fragment loss can invalidate the whole datagram, and some paths drop fragments or oversized packets."),
  "tcp-tuning-knobs": T("TCP tuning should follow a measured bottleneck: socket buffers affect available buffering, TCP_NODELAY changes Nagle behavior, keepalive probes detect some idle-peer failures, and backlog settings affect connection admission. None is a universal speed switch. Compare packet traces, queue depths, CPU cost, and tail latency before and after a change.", "A latency-sensitive protocol sends several tiny writes per request. Test batching and TCP_NODELAY under realistic request patterns instead of changing all system-wide defaults.", "Baseline|Measure small-message latency|Known workload;Change|Batch writes or alter Nagle behavior|One variable;Compare|Inspect packets and p99|Keep only useful change", "TCP keepalive is not a replacement for application deadlines or proof that a business operation completed.", "Why can larger buffers worsen latency?", "They can permit more queued data, increasing waiting time under congestion even when loss decreases."),
  "dns-hierarchy": T("DNS distributes naming authority through a hierarchy of zones. Root servers refer resolvers toward top-level-domain servers, which delegate toward authoritative zones. Authoritative servers answer for their zones; recursive resolvers perform lookup work and cache results for clients. Delegation boundaries need not match every visible dot in a hostname.", "Resolve api.example.com from an empty resolver cache by following root, com, and example.com authority information.", "Root|Refer to com servers|Delegation;TLD|Refer to example.com authority|Zone ownership;Authority|Return api record|Answer can be cached", "Root servers do not normally store the final address for every Internet hostname.", "Why is delegation scalable?", "Each authority manages its portion of the namespace, while caching reduces repeated traversal and avoids one central database serving every answer."),
  "recursive-vs-iterative": T("A recursive query asks a server to obtain the final result or error on the client's behalf. Iterative resolution accepts referrals and queries the next relevant authority. A stub client commonly uses recursion with a resolver, while that resolver iterates through the hierarchy. Cache hits can eliminate most upstream queries.", "A laptop asks its configured resolver for an address. The resolver follows referrals and returns one final answer to the laptop.", "Stub|Requests recursive answer|Delegates lookup work;Resolver|Queries authorities iteratively|Follows referrals;Return|Final answer or error|Client need not walk hierarchy", "Recursive and authoritative roles can be implemented together, but their responsibilities are different.", "Why restrict open recursion?", "Unrestricted resolvers can be abused and consume resources for unrelated clients; recursion should follow the intended service policy."),
  "dns-record-types": T("A and AAAA map names to IPv4 and IPv6 addresses; CNAME aliases a name; MX selects mail exchangers; NS delegates authority; TXT carries text-based data; SOA describes zone authority metadata; PTR supports reverse naming; SRV describes selected service endpoints. Record type semantics matter more than treating DNS as a generic key-value store.", "A mail sender queries MX for a domain, then resolves the selected exchanger's address rather than assuming the domain's web-server A record handles mail.", "MX|Find preferred mail exchanger|Mail-specific lookup;A or AAAA|Resolve exchanger hostname|Network endpoint;Connect|Use mail protocol|Different from web endpoint", "A CNAME is not an HTTP redirect and does not change the browser's requested URL.", "Why can a website and mail service use different hosts?", "Different record types express different service roles, so web addressing and mail exchange routing are independent."),
  "dns-caching-and-ttls": T("DNS caches retain answers for their remaining TTL, reducing lookup latency and authority load. Negative answers can also be cached. Lowering a TTL affects newly fetched data, not necessarily entries already cached under an older value. DNS updates therefore propagate according to existing cache state rather than instantly.", "An answer cached with TTL 300 at time zero can remain until time 300 even if the authoritative record changes at time 60.", "t=0|Cache old answer for 300 seconds|Valid cached data;t=60|Authority changes record|Cache not pushed automatically;t=300|Entry expires|Resolver can fetch new answer", "A short TTL does not force existing TCP connections to reconnect to the new address.", "How should a planned migration use TTLs?", "Lower them sufficiently before the cutover, wait for older entries to age out, and account separately for connection reuse and client behavior."),
  "anycast-and-geodns": T("Anycast advertises one IP prefix from multiple locations so routing selects a reachable instance according to network policy. GeoDNS returns different answers based on available location or resolver information. Neither guarantees the geographically nearest server or identical decisions for every client. Health, caching, routing changes, and session continuity matter.", "Two DNS resolvers query the same service name and receive different regional addresses. Separately, one anycast address can reach different sites from different networks.", "GeoDNS|Answer varies by query context|Name-level selection;Anycast|Same address advertised at sites|Route-level selection;Failure|Adjust answers or announcements|Convergence and caches apply", "Resolver location can differ from the end user's location, producing imperfect geographic decisions.", "Why can anycast complicate long sessions?", "A route change may steer packets to another site that lacks the original connection state unless the architecture handles it."),
  "doh-and-dot": T("DNS over HTTPS and DNS over TLS encrypt transport between a client and its chosen resolver. DoH uses HTTPS; DoT uses a dedicated TLS-based DNS transport. They protect that hop from passive observation and modification but do not make the resolver untrusted or prove authoritative data authenticity by themselves.", "A laptop uses encrypted DNS to a public resolver. The local network no longer sees plain DNS questions, but the resolver still processes those names.", "Client|Build DNS question|Resolver choice matters;Encrypt|DoH or DoT connection|Protected transport hop;Resolver|Sees and resolves query|Trust boundary remains", "Encrypted DNS and DNSSEC address different threats and can be used together.", "Does DoH hide every destination from the network?", "No. Traffic addresses and other metadata remain observable, and broader privacy depends on the rest of the connection stack."),
  "dnssec": T("DNSSEC adds signatures and a chain of trust so validating resolvers can authenticate DNS data and authenticated denial of existence. It does not encrypt queries. Validation depends on correct delegations, keys, signatures, and time. A bogus signed chain should fail validation rather than silently return untrusted data as secure.", "A zone rotates keys but publishes inconsistent delegation information. Validating resolvers can return failure even while nonvalidating lookups appear to work.", "Fetch|Receive records and signatures|Signed data;Validate|Follow trust chain|Keys and time checked;Reject|Chain inconsistent|Do not claim authentic answer", "DNSSEC does not prove that the named service is honest or replace TLS certificate validation.", "Why can clock errors matter?", "Signature validity periods are time-bound, so an incorrect clock can make otherwise valid signatures appear expired or not yet valid."),
  "debugging-dns": T("Debug DNS by comparing the client stub, configured recursive resolver, and authoritative answers. dig and nslookup expose record types and response codes; dig can show TTLs and delegation behavior. Separate NXDOMAIN, empty answers, SERVFAIL, and timeout. Also inspect search suffixes, split-horizon configuration, and address-family differences.", "A service resolves internally but not externally. Query the intended internal resolver directly and compare authority rather than repeatedly flushing unrelated caches.", "Client|Check resolver configuration|Correct network context;Query|Compare recursive and authoritative answers|Record type and status;Explain|Identify split view or stale cache|Targeted correction", "A successful A lookup does not prove AAAA, MX, or a search-suffixed name behaves the same way.", "What distinguishes NXDOMAIN from timeout?", "NXDOMAIN is a negative naming answer; timeout means no usable response arrived within the waiting period."),
  "http-request-response-anatomy": T("An HTTP request expresses a method, target, metadata fields, and optional content; a response includes status, fields, and optional content. HTTP/1.1 serializes these differently from binary-framed HTTP/2 and HTTP/3, but core semantics remain. Message framing must be unambiguous so intermediaries agree on where one message ends.", "A GET for /orders/7 includes authority information and receives status 200 with JSON content and an explicit media type.", "Request|GET /orders/7|Select resource;Response|200 with application/json|Status and representation;Consume|Parse body under framing rules|Handle errors separately", "Content-Type describes representation format; it is not a guarantee that untrusted content is valid or safe.", "Why is ambiguous message length dangerous?", "Different parsers can disagree on boundaries, leading to desynchronization and request-smuggling risks."),
  "http-methods-and-idempotency": T("Safe methods are intended to retrieve without requested state change; idempotent methods have the same intended effect when repeated. GET is safe, PUT and DELETE are idempotent by semantics, and POST is not generally idempotent. Response status can differ across retries even when the intended effect remains idempotent.", "Deleting an already deleted resource may return 404 after an initial 204. The final resource state is still absent, satisfying idempotent intent.", "First DELETE|Resource removed|Response may be 204;Retry DELETE|Already absent|Response may be 404;State|Resource remains absent|Effect is idempotent", "Using GET for a state-changing action violates safe-method expectations and can interact badly with caches or prefetching.", "How can a payment POST be retried safely?", "Use an application idempotency key with durable deduplication and a defined response-replay policy, rather than relying on POST semantics."),
  "status-codes": T("HTTP status families distinguish informational responses, success, redirection, client-side request issues, and server-side failures. Individual codes carry specific semantics: 401 requests authentication, 403 denies access, 404 indicates no available representation at the target, 429 signals rate limiting, and 503 indicates temporary unavailability. Retry policy must consider operation semantics too.", "A client receives 429 with a Retry-After value. Respect the delay and the request deadline rather than immediately multiplying requests.", "Request|Rate limit exceeded|Server returns 429;Policy|Read Retry-After|Bound by deadline;Retry|Wait and retry only if safe|Avoid amplification", "Not every 5xx should be retried blindly, and a timeout does not prove the server did nothing.", "How do 401 and 403 differ?", "401 concerns required or failed authentication with the relevant challenge; 403 means the server refuses the request under its authorization policy."),
  "http-headers": T("HTTP fields carry representation metadata, caching policy, authentication, negotiation, and connection-related information. End-to-end fields and hop-specific behavior must be handled correctly by intermediaries. Header names are case-insensitive, but values follow field-specific rules. Duplicate-field handling and trust of forwarded identity headers require explicit policy.", "A proxy receives a client-supplied X-Forwarded-For value. It should not automatically treat the first supplied address as authenticated origin identity.", "Client|Supplies untrusted fields|Can forge metadata;Proxy|Rewrites trusted forwarding chain|Boundary enforcement;Backend|Trusts only configured proxy policy|Avoid spoofed identity", "Do not concatenate every repeated header generically; some fields have special combination rules.", "Why does Vary matter to a cache?", "It identifies request fields that affect representation selection so incompatible variants are not reused as the same cached response."),
  "http-1-vs-2-vs-3": T("HTTP/1.1 uses ordered messages on TCP connections; HTTP/2 adds binary frames and multiplexed streams over TCP; HTTP/3 maps HTTP semantics onto QUIC streams. Multiplexing reduces application-level serialization, while transport behavior determines loss-related blocking. Version choice interacts with proxies, network support, connection reuse, and server implementation.", "Fetch several resources over one connection under packet loss. HTTP/2 streams can share a TCP delivery stall; HTTP/3 can continue unrelated streams when their data is available.", "H1|Requests share ordered connection use|Limited concurrency per connection;H2|Multiplex frames over TCP|Shared transport ordering;H3|Use QUIC streams|Independent stream delivery", "HTTP/3 does not guarantee lower latency for every workload or network.", "What remains common across versions?", "Methods, status semantics, representation metadata, caching rules, and application-level correctness requirements largely remain the same."),
  "persistent-connections": T("Persistent connections reuse established transport state across requests, avoiding repeated handshake costs. HTTP/1.1 pipelining permits multiple outstanding requests but responses remain ordered; multiplexing interleaves independent streams in HTTP/2 or HTTP/3. Connection limits and idle timeouts must balance reuse against resource retention and stale connections.", "Three sequential requests reuse one TLS connection. Setup is paid once, but an idle timeout may close it before a fourth request arrives.", "First|Establish connection and TLS|Setup cost;Reuse|Send next requests|Amortized setup;Idle|Peer may close connection|Handle stale pool entry", "Keep-alive is not a promise that a connection will remain open forever.", "Why did HTTP/1.1 pipelining struggle?", "Ordered responses and intermediary behavior made head-of-line delays and compatibility difficult; multiplexed streams address different parts of that problem."),
  "http-2-internals": T("HTTP/2 divides messages into frames associated with stream identifiers, multiplexes them over one TCP connection, and compresses field blocks using HPACK. Flow control applies at both stream and connection levels for DATA. Stream errors and connection errors have different scope, while TCP loss can still delay all delivered bytes.", "Stream 1 sends a large response while stream 3 sends a small response. Frames can interleave, subject to flow-control budgets and scheduling.", "Streams|IDs 1 and 3|Independent HTTP exchanges;Frames|Interleave DATA and metadata|One TCP connection;Flow control|Check stream and connection windows|Both can constrain sending", "HPACK compression is not encryption; TLS provides transport confidentiality when used.", "Why can one blocked connection window affect multiple streams?", "Connection-level flow control is a shared budget, so available per-stream credit alone may not permit sending."),
  "http-3-and-quic": T("QUIC runs over UDP while implementing reliable streams, congestion control, integrated TLS security, and connection identifiers. HTTP/3 uses those streams for HTTP exchanges. Loss blocks the affected stream's ordered delivery rather than necessarily every stream. Connection migration can preserve a connection across address changes under validated protocol rules.", "A phone changes networks during a QUIC session. Connection identifiers and path validation can support continuity rather than relying solely on the original IP/port tuple.", "Original path|Connection ID identifies session|Established keys;New path|Address changes|Validate path reachability;Continue|Use validated path|Application connection may survive", "QUIC is not unreliable merely because its carrier is UDP; it supplies its own transport mechanisms.", "Why treat 0-RTT data carefully?", "Early data can be replayed under the protocol threat model, so applications must restrict it to operations safe under replay."),
  "tls-handshake": T("TLS establishes authenticated cryptographic context and derives traffic keys. In a simplified TLS 1.3 full handshake, the client offers parameters and key share, the server selects parameters and proves identity with its certificate and signature, and finished messages authenticate the handshake. Resumption and client authentication change the sequence.", "A browser connects to a server with a certificate for a different hostname. Encryption negotiation alone is insufficient; hostname validation must reject the mismatch.", "ClientHello|Offer parameters and key share|No application trust yet;Server proof|Certificate and handshake authentication|Validate chain and hostname;Finished|Confirm transcript and keys|Protected application data", "Disabling certificate checks turns encrypted communication into a connection that may be with an impostor.", "What does forward secrecy aim to protect?", "With appropriate ephemeral key exchange, later compromise of a long-term authentication key should not reveal previously recorded session traffic."),
  "certificates-and-pki": T("A certificate binds an identity to a public key under an issuer's signature. Validation checks a trusted chain, validity period, intended use, and requested hostname, with revocation behavior depending on client policy. The server must also prove possession of the corresponding private key. Trust stores determine which roots the client accepts.", "A server sends its leaf certificate but omits a required intermediate. Some clients fail chain building even though the leaf's dates and hostname look correct.", "Leaf|Names requested service|Public key binding;Chain|Link through intermediates to trust root|Issuer validation;Proof|Server demonstrates private-key control|Authenticated handshake", "A self-signed certificate can be appropriate in an explicitly managed trust model, but is not automatically trusted by public clients.", "Why is a certificate not a secret?", "It contains public identity/key information; the private key must remain protected and is what enables proof of possession."),
  "http-caching": T("HTTP caches store reusable responses according to freshness, validation, and cache-control rules. Private browser caches differ from shared proxies or CDNs. ETags enable conditional validation; Vary separates representations selected by request fields. Cache keys and authorization policy must prevent one user's personalized response from being served to another.", "A cached response becomes stale and the client sends If-None-Match. A 304 confirms reuse of the stored representation without retransmitting its body.", "Store|Save response and ETag|Freshness policy;Validate|Send If-None-Match|Cached body retained;304|Reuse stored representation|Refresh metadata appropriately", "no-cache permits storage with validation requirements; no-store instructs against storing the response.", "Why can caching authenticated pages be dangerous?", "A shared cache with an incomplete key or incorrect directives can expose personalized content across users."),
  "websockets": T("WebSockets provide framed bidirectional messaging over a long-lived connection. The opening procedure, message framing, ping/pong, and close exchange are distinct from repeatedly issuing HTTP requests. Applications still need authentication, message-size limits, backpressure, reconnect behavior, and state recovery after disconnection.", "A chat client reconnects after losing its socket. Resume from a server-issued message cursor rather than assuming all messages sent before disconnect were delivered.", "Connect|Authenticate session|Long-lived channel;Exchange|Bidirectional messages|Bound queues;Reconnect|Resume with cursor|Recover missed events", "A live socket is not durable message storage or proof that the user consumed a message.", "Why add application message IDs?", "They support deduplication, acknowledgements, and replay decisions beyond transport-level byte delivery."),
  "server-sent-events": T("SSE sends a server-to-client event stream using HTTP with text/event-stream framing. Event IDs can support reconnection, while the client sends separate requests for upstream actions. Intermediaries must allow streaming rather than buffering indefinitely. Heartbeats, replay retention, authentication, and disconnect cleanup remain application concerns.", "A dashboard receives event IDs 40 and 41, disconnects, and reconnects with the last known ID. The server can replay retained events after 41.", "Stream|Send event id 41|Client records progress;Disconnect|Connection ends|State retained locally;Resume|Request after id 41|Replay if available", "SSE reconnection alone does not guarantee an infinite history or exactly-once handling.", "When choose SSE over WebSockets?", "When updates are primarily server-to-client and ordinary HTTP requests suffice for client actions, simplifying protocol and infrastructure needs."),
  "long-polling-vs-sse-vs-websockets": T("Long polling holds a request until data or timeout, then the client repeats it. SSE maintains a server-to-client stream. WebSockets support bidirectional framed communication. Choose by update direction, frequency, infrastructure compatibility, and recovery needs; all require connection limits and an explicit resume strategy.", "A low-frequency notification service may use long polling; a live dashboard fits SSE; interactive collaboration may need WebSocket bidirectionality.", "Rare updates|Repeated held requests|Long polling option;Server feed|Continuous downstream events|SSE option;Interactive|Frequent two-way messages|WebSocket option", "A protocol choice does not eliminate reconnect races or message deduplication.", "What question should come before choosing?", "Clarify directionality, latency target, update rate, client population, proxy support, and what must happen after missed messages."),
  "grpc-and-protobuf": T("gRPC defines remote methods and commonly uses HTTP/2 with Protocol Buffers serialization. Unary and streaming RPCs have different lifecycle and flow-control behavior. Deadlines, cancellation, status codes, and schema evolution are part of the contract. Binary serialization reduces some overhead but does not make distributed calls equivalent to local function calls.", "An upstream RPC has 200 ms remaining. Pass an appropriate deadline downstream rather than starting a new unlimited wait at each service hop.", "Caller|Sets deadline|Bounded operation;Server|Propagates remaining budget|Dependent work constrained;Cancel|Stop useful work after deadline|Release resources", "Reusing a removed protobuf field number can reinterpret old data incorrectly.", "Why reserve removed field numbers?", "Wire compatibility depends on stable numeric identifiers; reserving them prevents accidental reuse with incompatible meaning."),
  "graphql-networking": T("GraphQL typically sends operations to an HTTP endpoint, but transport concerns remain: query size, response size, caching, authentication, batching, and cancellation. Flexible queries can produce expensive server work or oversized payloads. Persisted operations and explicit complexity limits help bound cost, while subscriptions need a separate live-update transport contract.", "A single query requests deeply nested customer orders and items. One HTTP request can still trigger many backend calls and a very large response.", "Request|One GraphQL operation|Flexible selection;Resolve|Fan out to backend data|Potential N+1 work;Bound|Apply batching and cost limits|Predictable resources", "Fewer HTTP requests do not automatically mean less total work or lower latency.", "Why is shared caching harder for arbitrary POST queries?", "Cache keys and policy must include operation, variables, and authorization context; generic URL-only caching cannot safely distinguish results."),
  "mqtt": T("MQTT uses broker-mediated publish/subscribe with topics and small messages suitable for constrained clients. QoS levels provide different delivery handshakes: at-most-once, at-least-once, and protocol-level exactly-once delivery. Retained messages and session state have specific semantics. Application side effects still need deduplication and lifecycle design.", "A sensor publishes a measurement with QoS 1 and reconnects after an uncertain acknowledgement. The consumer may see a duplicate and should use a measurement identifier.", "Publish|Measurement M7 sent|QoS 1;Uncertain|Acknowledgement lost|Sender may retry;Consume|Deduplicate M7 if required|One business observation", "Protocol-level delivery guarantees do not automatically make an external database transaction exactly once.", "What is a retained message for?", "It lets a broker provide the latest retained value for a topic to new subscribers, rather than acting as a complete historical event log."),
  "smtp-ftp-ssh": T("SMTP transfers mail between clients and servers with store-and-forward behavior. FTP separates control and data connections, complicating NAT and firewall handling. SSH provides authenticated encrypted remote access and tunneling; SFTP is an SSH-based file protocol distinct from FTP or FTPS. Security depends on the chosen protocol mode and identity checks.", "A firewall permits an FTP control connection but file transfer fails because the required data connection path is not allowed.", "Control|FTP commands succeed|Control channel open;Data|Separate connection required|Firewall or NAT issue;Diagnose|Inspect mode and data path|Do not blame credentials alone", "SFTP and FTPS are different protocols, despite both being used for protected file transfer.", "Why does SSH host-key validation matter?", "It authenticates the server endpoint; accepting an unexpected key without investigation can allow an impostor to intercept the session."),
  "what-is-a-socket": T("A socket is an operating-system communication endpoint with protocol, address, state, and buffering. A listening TCP socket accepts new connections; each accepted connection has its own socket. The descriptor is a process-local handle, while the transport tuple identifies communication context. Socket APIs also support local domains and datagram protocols.", "A server listens on port 8080 and accepts three clients. It retains one listener plus three connected sockets, not one shared stream for all clients.", "Listen|One socket accepts arrivals|Port 8080;Accept|Create connected endpoint per client|Separate stream state;Serve|Track each connection independently|Own buffers and lifecycle", "A port number alone does not uniquely identify every connection on a host.", "How can many clients use one server port?", "Their connection tuples differ in peer address and port, allowing transport demultiplexing to distinct established sockets."),
  "tcp-socket-programming": T("A TCP server typically creates, binds, listens, and accepts; a client connects. Both sides send and receive an ordered byte stream, so framing must define message boundaries. Robust loops handle short reads, partial writes, EOF, interruption, deadlines, and cleanup. Received bytes must be validated before allocating based on a claimed length.", "A length-prefixed five-byte message arrives as a partial header, the remaining header, and several payload chunks. Accumulate until a complete validated frame exists.", "Header|Only two of four bytes arrive|Keep parser state;Length|Full prefix says five|Check maximum size;Payload|Collect five bytes|Emit exactly one message", "One recv does not correspond to one send, even on a local machine.", "Why cap frame length before allocation?", "An untrusted peer can claim an enormous size and exhaust memory unless the protocol enforces a maximum."),
  "udp-socket-programming": T("UDP applications use datagram send and receive operations, often obtaining the peer address with each message. A connected UDP socket selects a default peer and filtering behavior but does not establish TCP-style reliability. Design request identifiers, size limits, duplicate handling, and retransmission policy when the application needs them.", "Send request ID 9 and receive a delayed duplicate response after request 10 begins. Match by request identity rather than assuming the next datagram answers the latest request.", "Send|Request ID 9|Start deadline;Receive|Duplicate response 9 arrives|May be late;Match|Use ID and peer validation|Ignore stale response", "UDP source addresses can be spoofed in some threat models; do not treat a datagram's address as authenticated identity.", "Why should UDP application retries be bounded?", "Unlimited retransmission can amplify congestion and keep obsolete work alive after the caller no longer needs it."),
  "multi-client-with-threads": T("A thread-per-connection server is straightforward because each worker can block independently, but stacks, scheduling, descriptors, and queued output limit scale. A bounded pool controls concurrency but needs admission and queue policies. Shared application state must be synchronized even when each connection has its own worker.", "A server creates one thread for every idle connection. Ten thousand idle clients consume resources without doing useful work, motivating limits or an event-driven model.", "Accept|New client arrives|Thread allocation;Idle|Worker blocks on read|Stack and descriptor retained;Limit|Bound clients and deadlines|Prevent resource exhaustion", "A thread pool does not automatically bound accepted sockets waiting outside the pool.", "Where should admission control happen?", "Before allocating unbounded per-client resources, with explicit queue limits and a clear overload response."),
  "non-blocking-io-and-select": T("Nonblocking descriptors return when an operation cannot currently progress. select waits for readiness across sets of descriptors, after which the application attempts I/O and preserves partial state. Readiness can change before the call, so EAGAIN remains valid. Platform descriptor-set limits and scanning costs constrain this model at high scale.", "A writable socket accepts only part of an output buffer. Keep the remaining bytes and continue after later write readiness.", "Ready|Socket reported writable|Progress possible;Write|Send 30 of 100 bytes|Partial completion;Retain|Queue remaining 70|Wait for next opportunity", "Do not register permanent write interest when no data is pending; it can spin the event loop.", "Why keep nonblocking mode after select?", "Another actor or state change can consume readiness before the operation; nonblocking mode prevents an unexpected indefinite block."),
  "epoll-kqueue-iocp": T("epoll on Linux and kqueue on BSD-derived systems expose event notification facilities, while Windows IOCP dispatches completion records for submitted asynchronous operations. Their details differ, so a portable event layer must normalize ownership and lifecycle rather than pretending readiness and completion are identical. Cancellation and descriptor reuse deserve particular care.", "A reactor receives readability and then issues a read. A completion-based design receives the result of a read submitted earlier.", "Reactor|Notification says read may progress|Issue operation now;Proactor|Read was submitted earlier|Receive completion result;Adapter|Normalize application state changes|Respect native lifecycle", "Closing a handle does not justify ignoring outstanding callbacks or reusing request memory prematurely.", "What should a portable abstraction expose?", "Operation identity, byte counts, errors, cancellation state, and resource ownership with documented backend-specific limitations."),
  "async-networking": T("Asyncio tasks cooperate on an event loop, while Java NIO provides channels, buffers, and selector-based readiness facilities; higher-level Java APIs can use other models. Async code must yield at suitable operations and preserve state across suspension. Blocking libraries or CPU loops can stall the event thread despite asynchronous syntax.", "An asyncio handler awaits socket input but calls a slow blocking file API afterward. Other tasks stop progressing during that blocking call.", "Await|Socket wait yields control|Other tasks run;Block|Synchronous file call occupies loop|Tasks delayed;Offload|Use suitable bounded executor|Loop stays responsive", "await does not make arbitrary called code nonblocking.", "Why propagate cancellation through async work?", "The caller may have abandoned the operation; dependent work should release resources and stop when safe rather than continuing indefinitely."),
  "concurrent-tcp-server": T("A concurrent echo server needs more than accept and send: it must track clients, preserve unsent bytes, handle EOF and errors, enforce limits, and release resources on every path. An event-driven implementation separates listening, reading, writing, and closing states. Echoing bytes is simpler than parsing messages but still demonstrates stream and backpressure rules.", "Client A sends 100 bytes while client B reads slowly. Queue only a bounded amount of B's echo data and continue servicing A fairly.", "Read|Receive available bytes|Append bounded output;Write|Send only accepted bytes|Retain remainder;Close|Drain or cancel by policy|Remove events and descriptor", "An unlimited echo output buffer lets a slow reader exhaust server memory.", "What tests should an echo server pass?", "Partial writes, half-close, abrupt reset, idle timeout, many clients, slow readers, and shutdown without leaked descriptors."),
  "wireshark-deep-dive": T("Wireshark decodes captured frames into protocol fields and conversation views. Capture filters limit what is recorded; display filters select what is shown afterward. Sequence analysis and timing can suggest retransmission or handshake issues, but capture location, dropped capture packets, encryption, and offload artifacts affect interpretation.", "Filter one TCP conversation and compare SYN, SYN-ACK, ACK, request, and first response timestamps to separate connection setup from server response delay.", "Select|Choose conversation and time window|Relevant packets;Inspect|Compare sequence and timing|Locate delay;Correlate|Check application logs|Validate interpretation", "A packet absent from one capture may reflect capture loss or placement, not network loss.", "Why can checksums appear incorrect locally?", "Checksum offload may let the capture observe packets before hardware fills the final checksum."),
  "tcpdump": T("tcpdump captures packets with expressions selecting interfaces, hosts, ports, and protocols. Use bounded counts or capture rotation, appropriate snapshot lengths, and a narrow scope. Captures can contain sensitive payloads, and privileges depend on platform setup. Saved packet files support later analysis without repeatedly reproducing the incident.", "On an authorized local test, capture a bounded set of packets for TCP port 8080 and compare timestamps with one failing request.", "Scope|Select interface and port|Relevant traffic only;Capture|Bound packet count and duration|Control size;Analyze|Match flow and timestamps|Correlate request failure", "Capturing only one direction or the wrong interface can produce a misleading incomplete trace.", "Why set a suitable snapshot length?", "Too short truncates needed headers or payload; too large increases storage and exposure without necessarily helping the diagnosis."),
  "netstat-ss-lsof": T("Socket listing tools connect protocol state and local/remote endpoints, while lsof-style tools map open resources to processes. ss is commonly used on Linux for detailed socket information. A listening socket differs from an established connection, and permission restrictions can hide process ownership. Check network namespaces when the expected socket is missing.", "Port 8080 is occupied. Identify the listener's owning process and namespace before changing ports or terminating unrelated services.", "List|Find listening endpoint|Address and port;Own|Map socket to process|Check privileges;Context|Confirm namespace and service|Choose correct target", "Binding only to loopback makes a service inaccessible externally even when it is listening correctly.", "Why can a host view miss a container listener?", "The socket may live in another network namespace, with separate interfaces and forwarding configuration."),
  "curl-and-wget": T("curl and wget help isolate HTTP behavior from browser rendering. Inspect status, redirects, headers, certificate validation, and phase timing. curl timing fields can separate name lookup, connection, TLS, first byte, and total transfer. Command-line success may still differ from browser behavior due to cookies, proxies, CORS, and authentication context.", "Use a test endpoint and curl timing output to show that TLS setup is quick but first-byte time is long. Investigate server work or upstream waiting.", "Connect|DNS and TLS complete quickly|Setup not dominant;Wait|First byte delayed|Server or dependency time;Transfer|Body arrives quickly|Payload throughput adequate", "Following redirects hides intermediate responses unless they are inspected deliberately.", "Does curl success prove a browser request will succeed?", "No. Browser security policies and session context can differ even when the underlying network request is possible."),
  "traceroute-mtr-ping": T("Ping samples end-to-end round-trip behavior; traceroute estimates hop sequence; mtr combines repeated probes with per-hop statistics. Router reply policy can differ from forwarding behavior, and reverse paths can vary. Interpret sustained destination impact more strongly than isolated intermediate-hop reply loss, and compare probes with the actual application protocol.", "One router shows 50% probe reply loss, but every later hop and the destination show none. The likely issue is reply rate limiting rather than transit loss.", "Intermediate|Some probe replies absent|Control-plane policy possible;Later hops|No corresponding loss|Packets still forwarded;Endpoint|Application healthy|Avoid false bottleneck claim", "RTT to a hop includes the return path, so subtracting adjacent RTTs is not a precise one-way link latency measurement.", "What would strengthen a loss diagnosis?", "Persistent destination loss correlated with application retransmissions and captures from appropriate endpoints."),
  "iperf-bandwidth-testing": T("iperf-style tests measure achievable transport throughput between controlled endpoints. TCP and UDP tests answer different questions, and parallel streams, duration, direction, CPU, window sizing, and path capacity influence results. Test traffic itself consumes bandwidth, so use an agreed environment and compare against real application characteristics.", "A single TCP stream reaches less throughput than several parallel streams. Investigate per-flow window, RTT, and CPU limits before concluding the link is slower than advertised.", "Single flow|Measure baseline throughput|Known direction;Parallel|Run several controlled streams|Aggregate changes;Explain|Check windows RTT and CPU|Find limiting factor", "A throughput benchmark does not measure database response time or application serialization cost.", "Why test both directions?", "Access links, routing, shaping, and endpoint performance can be asymmetric."),
  "reading-a-real-pcap": T("Packet analysis should reconstruct a timeline and test competing explanations rather than label every repeated sequence as the root cause. Consider capture placement, retransmissions, receive windows, resets, and application boundaries. Encrypted traffic still exposes useful timing and transport metadata, but cannot directly reveal protected application content without appropriate keys and authorization.", "In this constructed incident, a receiver advertises zero window while the sender pauses. The application was stalled on a lock and stopped reading; the path itself had spare capacity.", "Capture|Receiver advertises zero window|Buffer pressure;Sender|Pauses new data|Obeys flow control;Application|Lock stall stops reads|Root cause beyond network", "This is an original illustrative incident, not a claim about a supplied production capture or a named company's outage.", "What evidence confirms the hypothesis?", "Correlate zero-window periods with receive-queue growth and application lock waits, then verify that fixing the reader restores progress."),
  "latency-vs-throughput-vs-bandwidth": T("Latency is time to complete a defined operation, throughput is useful work completed per unit time, and bandwidth is a capacity bound for a link or path. A high-bandwidth path can have high latency. Units and measurement boundaries matter: payload throughput differs from wire rate, and one request's latency differs from aggregate concurrency.", "A 100 Mbps path with 100 ms RTT can carry substantial data, yet ten sequential request-response dependencies still incur roughly one second of RTT alone.", "Capacity|100 Mbps link|Rate bound;Dependency|Ten sequential round trips|100 ms each;Delay|About one second minimum RTT work|Before server and transfer costs", "More bandwidth does not remove serial round-trip dependencies.", "When does batching help?", "It can amortize per-request overhead and round trips, but increases batching delay and may enlarge responses."),
  "bandwidth-delay-product": T("The bandwidth-delay product estimates data needed in flight to fill a path: bandwidth multiplied by round-trip time, using consistent units. Sender and receiver windows must permit sufficient outstanding data, while congestion control and application production also constrain throughput. It is a capacity estimate, not a command to allocate unlimited buffers.", "At 100 Mbps and 80 ms RTT, BDP is 8 megabits, or about 1 MB in decimal units. A 64 KiB flight limit cannot fill that path under this simple model.", "Convert|100000000 bits per second|RTT 0.08 seconds;Multiply|8000000 bits in flight|1000000 bytes;Compare|64 KiB below BDP|Window can limit rate", "Confusing bits with bytes produces an eightfold sizing error.", "What is the simple window-limited throughput bound?", "Approximately window bytes divided by RTT seconds, before accounting for loss, protocol overhead, and other bottlenecks."),
  "where-latency-comes-from": T("End-to-end latency includes propagation, serialization, queueing, processing, setup, and application dependencies. Propagation depends on physical distance; serialization depends on size and link rate; queueing changes with load. Tail latency often rises sharply near saturation even when average service time remains similar.", "A 1 MB payload takes about 80 ms to serialize at 100 Mbps before considering RTT, server processing, or congestion.", "Serialize|8 megabits at 100 Mbps|80 ms;Propagate|Travel across path|Distance cost;Queue|Wait behind competing traffic|Load-dependent delay", "Do not add round trips that overlap or assume every request always pays a fresh connection handshake.", "Why is p99 sensitive to utilization?", "Bursts and variability create queues near capacity, so a small fraction of requests can wait much longer than average."),
  "tcp-optimization": T("Optimize TCP from evidence: reduce unnecessary connection setup, batch suitable writes, ensure enough flight capacity for the path, and address loss or receiver stalls. Congestion algorithms, buffer limits, and offloads have workload-specific effects. Compare useful throughput and tail latency rather than maximizing a single kernel counter.", "A bulk transfer is limited by a small receive window on a high-RTT path. Validate that increasing permitted buffering helps without causing unacceptable queueing.", "Measure|Window and RTT limit flight|Known bottleneck;Change|Adjust relevant buffer policy|Controlled experiment;Verify|Throughput and p99|Check memory and queues", "Global tuning copied from another system can harm short-request workloads or consume excessive memory.", "Why measure application read speed first?", "A slow consumer can close the receive window; transport tuning cannot fix an application that does not drain data."),
  "connection-pooling": T("Connection pools reuse expensive established sessions and bound concurrent access to an upstream. Pool size, acquisition timeout, idle lifetime, maximum age, and health checks shape behavior. A pool can become a queueing bottleneck or overwhelm the upstream if oversized. Stale connections need safe recovery without blindly replaying non-idempotent work.", "Twenty workers share a pool of five connections. Requests wait for acquisition even though the network path is fast; include that wait in latency metrics.", "Acquire|Twenty callers seek five slots|Pool queue;Use|Five active upstream requests|Bounded concurrency;Release|Return healthy connection|Next waiter proceeds", "A larger pool can move the queue into the database and worsen total latency.", "Which timing should be separated?", "Pool acquisition, connection setup, upstream processing, and response transfer reveal different bottlenecks."),
  "http-caching-strategies": T("Choose cache policy by data volatility and privacy. Versioned static assets can use long freshness lifetimes; mutable data may use short freshness plus validators; sensitive personalized responses need carefully scoped storage policy. Stale-while-revalidate and invalidation strategies trade freshness for latency and availability under explicit requirements.", "Publish app.abc123.js with a content-derived filename and long freshness, while the HTML referencing it uses a shorter or validated policy.", "Asset|Versioned filename|Content identity stable;Cache|Reuse for long lifetime|Avoid repeated transfer;Deploy|HTML points to new hash|Old asset remains valid", "A long TTL on an unversioned mutable asset can leave clients using obsolete content.", "Why separate HTML and asset policy?", "HTML selects the current version, while immutable versioned assets can be cached safely for much longer."),
  "cdns-and-edge": T("A CDN places delivery and often caching near users, reducing origin load and some network distance. Cache keys, origin shielding, invalidation, and dynamic-request forwarding determine behavior. An edge hit and an origin miss have different latency paths. Personalized content and regional consistency require explicit policy.", "The first request in an edge region misses and fetches from origin; later requests hit until expiration or invalidation.", "Miss|Edge lacks object|Fetch from origin;Fill|Store cacheable response|Key and policy applied;Hit|Serve nearby copy|Origin work avoided", "A CDN cannot cache every dynamic response safely, and invalidation is not necessarily instantaneous everywhere.", "What would you monitor?", "Hit ratio by content class, origin request rate, miss latency, error rates, and correctness of cache variation and authorization."),
  "compression": T("Compression reduces transferred bytes at the cost of CPU, latency, and implementation complexity. Benefit depends on content entropy and size; already compressed images often gain little. Content negotiation must select supported encodings, and caches must distinguish variants. Sensitive data mixed with attacker-controlled input can create compression-related side channels.", "A 1 MB JSON response compresses to 200 KB. Compare saved network time with encoding CPU cost and avoid recompressing identical output unnecessarily.", "Original|1 MB structured text|Compressible redundancy;Encode|Produce 200 KB|CPU work required;Transfer|Send fewer bytes|Potential latency improvement", "Compression is not encryption and does not protect confidential content.", "When can compression hurt?", "For tiny or incompressible payloads, CPU and framing overhead can exceed transfer savings, especially on fast local networks."),
  "finding-bottlenecks": T("A network bottleneck investigation separates client queueing, DNS, connection setup, TLS, server work, transport transfer, and downstream dependencies. Correlate request traces with socket queues, retransmissions, CPU, and path measurements. Change one factor under a controlled workload and require improvement in the user-visible objective.", "Downloads are slow only for one region. Compare RTT, loss, edge hit ratio, and server time before increasing application worker count globally.", "Scope|One region affected|Geographic clue;Measure|Compare path and cache metrics|Separate server time;Experiment|Test alternate edge or route|Validate cause", "Correlation with a retransmission counter alone does not establish the dominant latency cause.", "Why use a known-size response?", "It controls payload variability, making transfer rate and setup overhead easier to compare across paths."),
  "fallacies-of-distributed-computing": T("The classic fallacies assume the network is reliable, latency is zero, bandwidth is infinite, the network is secure, topology never changes, there is one administrator, transport costs nothing, and the network is homogeneous. Treat each as a design question about failure, delay, capacity, trust, change, ownership, cost, or compatibility.", "A service calls a remote dependency as though it were a local function. A timeout, version mismatch, or regional partition exposes the missing assumptions.", "Assume|Remote call always succeeds quickly|Hidden fallacies;Fail|Delay or partial failure occurs|Local-call model breaks;Design|Deadlines retries and compatibility|Explicit distributed contract", "Listing the fallacies without changing timeout, ownership, and recovery behavior does not improve the system.", "Which assumption does a rolling upgrade challenge?", "Homogeneity and static topology: different versions and endpoints coexist, requiring compatible protocols and dynamic discovery."),
  "failure-modes-and-partitions": T("Distributed failures include delay, message loss, connection reset, partial service failure, and partitions that prevent some participants communicating. A timeout indicates uncertainty within a deadline, not proof that the operation never ran. Design must distinguish retryable transport uncertainty from application rejection and preserve correctness under ambiguous outcomes.", "A payment server commits an operation, but the reply is lost. The client times out and cannot infer whether charging occurred.", "Commit|Server records payment|Business effect completed;Lose|Reply does not reach client|Outcome hidden;Resolve|Query or retry with idempotency key|Avoid duplicate charge", "Treating every timeout as a clean rollback creates duplicate effects.", "What does a network partition require from the design?", "An explicit choice about which operations remain available and what consistency or reconciliation guarantees hold while communication is interrupted."),
  "retries-and-backoff": T("Retries can recover transient failures but multiply load during outages. Use bounded attempts, an overall deadline, exponential backoff with jitter, and a retry budget. Retry only operations whose semantics tolerate repetition or provide deduplication. Avoid independent retry loops at every layer that amplify one user request into many downstream calls.", "Three layers each allow three total attempts. In the worst case one request can cause 3 × 3 × 3 = 27 leaf attempts.", "Layer one|Three attempts|Outer policy;Layer two|Three per outer attempt|Nine calls;Layer three|Three per inner attempt|Twenty-seven leaf attempts", "Jitter spreads timing but does not make unlimited retries safe.", "Why keep one overall deadline?", "Per-attempt timeouts can otherwise add into a total wait far beyond the caller's useful lifetime."),
  "idempotency": T("Idempotency makes repeating an operation preserve the intended effect. For non-idempotent APIs, a stable key can identify a logical request and a durable record can coordinate effect execution and response replay. The key's scope, retention, payload consistency, and concurrent duplicate handling must be specified; an in-memory cache alone may lose protection on restart.", "Two retries submit payment key K with the same payload. Atomically create a deduplication record with the business effect or use a recoverable transaction protocol.", "First|Key K absent|Claim logical operation;Commit|Store effect and result consistently|Durable outcome;Duplicate|Key K already complete|Return recorded result", "Reusing the same key for a different payload should be rejected or handled under an explicit contract.", "Why must deduplication coordinate with the effect?", "A crash between separate writes can record a key without an effect or apply the effect without recording the key."),
  "circuit-breakers": T("A circuit breaker stops calls to a dependency after a defined failure threshold, allowing failures to return quickly while recovery is tested. Closed permits calls, open rejects them, and half-open allows bounded probes. It complements deadlines, concurrency limits, and retries but does not itself repair the dependency or guarantee a correct fallback.", "A failing inventory service triggers the breaker. After a cool-down, one bounded probe succeeds before normal traffic is gradually restored.", "Closed|Failures accumulate|Threshold reached;Open|Reject calls quickly|Protect resources;Half-open|Allow limited probe|Recover or reopen", "An overly broad breaker can block healthy endpoints, while synchronized probes can create another burst.", "What should count as a failure?", "Define dependency-health signals carefully; a valid business rejection such as out-of-stock is not necessarily infrastructure failure."),
  "load-balancing-l4-l7": T("Layer-4 balancing routes transport flows using endpoint information, while layer-7 balancing interprets application protocol data such as host or path. TLS termination determines what an intermediary can inspect. Algorithms, health checks, connection reuse, stickiness, and draining affect fairness and availability; request balance differs from connection balance.", "One long-lived connection carries thousands of HTTP/2 requests. A connection-level balancer may send them all to one backend despite equal connection counts.", "L4|Assign connection to backend|Flow granularity;Multiplex|Many requests share flow|Unequal request load;L7|Can select per-request backend|Needs application visibility", "Round-robin connections do not guarantee equal CPU or request load.", "When does sticky routing help and hurt?", "It can support local session state but reduces flexibility during scaling and failure; externalizing state often simplifies balancing."),
  "health-checks-and-discovery": T("Service discovery maps logical services to changing endpoints, while health checks decide whether an endpoint should receive work. Liveness, readiness, and dependency health answer different questions. Cached discovery data and delayed checks create convergence windows. Avoid health checks that overload dependencies or declare every replica unhealthy for a shared transient issue.", "A worker starts but has not loaded required data. It can be alive while not ready for traffic, so discovery should not route requests to it yet.", "Start|Process running|Liveness passes;Warm|Load required state|Readiness fails;Ready|Initialization complete|Eligible for traffic", "A successful TCP connection check does not prove the application can serve useful requests.", "Why separate liveness from readiness?", "Restarting a healthy but temporarily unready process can worsen recovery, while removing it from traffic may be sufficient."),
  "graceful-shutdown": T("Graceful shutdown stops new admission, advertises unavailability through discovery or protocol mechanisms, and allows bounded in-flight work to finish before forced termination. Existing connections, queued requests, streaming sessions, and background tasks need explicit policies. The grace period must fit upstream and orchestration deadlines.", "During deployment, remove a backend from new routing, drain active requests for up to 20 seconds, then cancel remaining work and close resources.", "Withdraw|Stop accepting new work|Routing update begins;Drain|Finish admitted requests|Bounded grace period;Terminate|Cancel leftovers and close|No indefinite shutdown", "Removing a discovery entry does not instantly close every cached or pooled connection.", "Why set a drain deadline?", "A hung request or endless stream must not prevent deployment or resource release forever."),
  "backpressure-and-rate-limiting": T("Backpressure reacts to downstream capacity, while rate limiting enforces a policy on arrivals. Token buckets permit bounded bursts and replenish capacity over time; concurrency limits cap in-flight work. These mechanisms complement queue bounds and deadlines. Choose units such as requests, bytes, or estimated cost that reflect the protected resource.", "A token bucket holds 10 tokens and refills 2 per second. A burst of 15 immediate requests admits 10 and rejects or delays 5 under the stated policy.", "Initial|Ten tokens available|Burst allowance;Burst|Fifteen requests arrive|Ten admitted;Refill|Two tokens each second|Future capacity restored", "Rate limits do not bound in-flight work when request durations become very long.", "Why add a concurrency limit?", "It directly caps retained active work, protecting memory and dependencies even when the arrival rate appears modest."),
  "tls-deep-dive": T("TLS combines peer authentication, key establishment, authenticated encryption, and record protection. Security depends on modern protocol configuration, certificate validation, key management, and endpoint integrity. Session resumption reduces setup work but has its own lifetime and replay considerations. SSL is historical terminology and obsolete SSL protocols should not be treated as equivalent secure choices.", "A reverse proxy terminates TLS and forwards plain HTTP internally. The external hop is protected, but the backend hop has a separate trust and transport decision.", "Client hop|TLS protects to proxy|External boundary;Termination|Proxy sees plaintext|Trusted processing point;Backend hop|Choose separate protection|Not automatically end-to-end", "TLS does not hide data from the endpoints where it is decrypted.", "When would mutual TLS help?", "When both sides need certificate-based peer identity, combined with authorization rules deciding what each authenticated identity may do."),
  "certificate-validation": T("Certificate validation checks hostname, trust chain, validity dates, usage constraints, and policy-dependent revocation information. Common failures include missing intermediates, wrong names, expired certificates, untrusted roots, and clock errors. Diagnose the exact failure instead of disabling validation, which removes the authentication property TLS is meant to provide.", "A service certificate covers api.example.com but the client connects by a raw IP not listed in the certificate. Validation correctly fails the identity match.", "Request|Client expects specific identity|Hostname or IP;Certificate|Presented names differ|Mismatch;Reject|Handshake cannot authenticate target|Fix identity or certificate", "Trusting any certificate that encrypts traffic defeats server authentication.", "Why can one client succeed while another fails?", "Trust stores, chain building, clocks, protocol support, and validation policies may differ between client environments."),
  "mitm-replay-downgrade": T("A man-in-the-middle attack attempts to impersonate or interpose between peers; replay resends previously valid data; downgrade tries to force weaker protocol choices. Authenticate peers and negotiation, use modern protected protocols, and add application freshness or idempotency where required. Encryption without identity checks does not prevent an active impostor.", "An attacker replays a valid-looking transfer request. A request nonce or idempotency record tied to authenticated context prevents repeating its business effect.", "Capture|Previously valid request exists|Replay candidate;Replay|Same operation submitted again|Transport alone insufficient;Check|Verify freshness or deduplicate|Reject repeated effect", "A timestamp alone needs a defined skew window and replay tracking to prevent repeated use within that window.", "Why is TLS early data special?", "Its replay properties require applications to restrict accepted operations to those safe under replay, even though the data is encrypted."),
  "ddos": T("DDoS attacks exhaust bandwidth, connection state, or application resources through distributed traffic. SYN floods target establishment state, amplification abuses response asymmetry, and slow-request attacks retain resources with minimal progress. Defense combines upstream capacity/filtering, protocol safeguards, admission limits, timeouts, and application cost controls.", "A slow client sends headers indefinitely. Enforce a header-completion deadline and minimum progress policy without relying only on total connection count.", "Connect|Client consumes connection state|Admission cost;Dribble|Headers never complete|Resources retained;Limit|Deadline and bounded state|Release stalled client", "Application rate limiting cannot recover an already saturated upstream network link by itself.", "Why coordinate with upstream providers?", "Volumetric traffic must often be filtered or absorbed before it reaches the constrained access link."),
  "dns-spoofing": T("DNS spoofing and cache poisoning aim to insert incorrect name-to-data results so clients reach an attacker's endpoint. Resolver hardening and response matching reduce opportunities, while DNSSEC authenticates signed data for validating clients. TLS identity checks remain necessary because naming and service authentication protect different boundaries.", "A poisoned address sends a browser to an impostor server. Correct TLS hostname and chain validation should still prevent authenticating that impostor as the requested site.", "Poison|Resolver returns wrong address|Naming compromised;Connect|Client reaches impostor|Wrong endpoint;Validate|TLS identity mismatch|Reject connection", "Encrypted DNS protects the client-resolver transport but does not automatically validate every authoritative answer.", "Why use multiple layers of verification?", "A failure in naming should not also defeat independent endpoint authentication and application authorization."),
  "firewalls-and-ids": T("Firewalls enforce traffic policy using addresses, ports, state, and sometimes application context. IDS detects suspicious activity, while IPS can block according to its deployment. Stateful rules track flows but still need correct direction, return-path, and timeout behavior. Logging must be scoped so useful evidence is not buried in noise.", "Allow a service's outbound database connection and its established replies while denying unrelated inbound connections. Test both normal traffic and policy violations.", "Policy|Permit required flow|Least necessary access;State|Track established exchange|Allow valid replies;Observe|Log meaningful denials|Investigate anomalies", "An open port is not proof that every application request through it is authorized.", "Why can asymmetric routing confuse stateful inspection?", "A device that sees only one direction may not build or maintain the expected connection state."),
  "vpn-protocols": T("VPN protocols create protected tunnels with different deployment models. IPsec operates at the IP layer with configurable security associations; WireGuard uses a compact key-based design; OpenVPN commonly uses TLS-based control and can run over supported transports. Routing, MTU, peer authentication, key rotation, and access policy remain essential regardless of protocol.", "A tunnel adds headers and reduces effective payload size. Small packets work while large transfers stall when path-size signaling is broken.", "Encapsulate|Add tunnel overhead|Smaller effective MTU;Transfer|Large packets exceed path capacity|Loss or fragmentation issue;Fix|Validate MTU and control messages|Restore large transfers", "A VPN authenticates tunnel peers under its configuration; it does not authorize every action on every reachable service.", "Why distinguish split and full tunneling?", "They route different traffic through the VPN, affecting privacy, capacity, access policy, and failure behavior."),
  "zero-trust": T("Zero trust avoids granting blanket authority merely because traffic originates inside a network boundary. Authenticate identities, authorize each relevant resource access, minimize privileges, and evaluate context under a defined policy. Segmentation, device posture, short-lived credentials, and observability can support the model, but it is an architecture rather than one product.", "A compromised internal worker presents a valid identity but requests an unrelated payroll API. Authorization should deny that operation despite its internal address.", "Authenticate|Verify worker identity|Known principal;Authorize|Check payroll permission|Specific resource policy;Deny|Internal location insufficient|Least privilege enforced", "Mutual TLS proves a peer identity; it does not automatically decide what that peer is allowed to do.", "What changes from perimeter-only trust?", "Access decisions rely on explicit identity and policy at resource boundaries instead of assuming internal network membership is enough."),
};
